# Global variable for dmesg logging
ENABLE_DMESG = True
THIS_FILE_NAME = os.path.basename(__file__)

MIN_EFA_VERSION = "2.12.1"
P6PLUS_MIN_KEFALND_VERSION = "1.1.1"
P6PLUS_INSTACES_PREFIX = [
    "p6-b200",
    "p6e-gb200",
    "p6-b300",
]
GDS_SUPPORTED_INSTANNCES = [
    "p5.48xlarge",
    "p5e.48xlarge",
    "p5en.48xlarge",
    "p6-b200.48xlarge",
]
MIN_CPT_OPT_TAG = 24

# TODO: update 26 with the correct tag
MIN_DEL_ALL_EFA_TAG = 26

START_MARKER = "# START, AUTO GENERATED BY AWS FSxL CONFIGURE EFA SCRIPT, DO NOT MODIFY"
END_MARKER = "# END, AUTO GENERATED BY AWS FSxL CONFIGURE EFA SCRIPT"
CPT_CONFIG_FILE_PATH = "/etc/modprobe.d/modprobe.conf"


def log_message(message: str) -> None:
    """Log a message with timestamp, optionally to kernel message buffer."""
    global ENABLE_DMESG

    timestamp = datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M:%S")
    full_message = f"{THIS_FILE_NAME}: [{timestamp}] {message}"

    if ENABLE_DMESG:
        try:
            with open('/dev/kmsg', 'w') as kmsg:
                kmsg.write(full_message + '\n')
        except Exception:
            # Write to kernel log is a best effort write, silently ignore failures
            pass

    print(full_message)


def log_print_exception() -> None:
    """Log exception traceback line by line."""
    to_print = traceback.format_exc().split("\n")
    for line in to_print:
        if line.strip():
            log_message(line)


def run_cmd(cmd: str, exit_on_err: bool = True) -> Tuple[int, str, str]:
    """Execute a shell command and return its result.

    Args:
        cmd: Command string to execute
        exit_on_err: If True, raise RuntimeError on non-zero exit code

    Returns:
        Tuple of (return_code, stdout, stderr)
    """
    try:
        result = subprocess.run(
            cmd, shell=True, capture_output=True, text=True, timeout=300)
        if exit_on_err and result.returncode != 0:
            raise RuntimeError(
                f"Failed to run \"{cmd}\". stdout={result.stdout}, stderr={result.stderr}")
        return (result.returncode, result.stdout, result.stderr)
    except subprocess.TimeoutExpired:
        raise RuntimeError(f"Command timed out after 300 seconds: \"{cmd}\"")
    except Exception as e:
        raise RuntimeError(
            f"Error: subprocess.run failed for \"{cmd}\": {str(e)}")


def run_cmd_in_parallel(cmds, max_concurrency=8) -> bool:
    """Execute shell commands in parallel.

    Returns: True if all cmds succeed, False otherwise
    """
    success = True
    success_cnt = 0
    with ThreadPoolExecutor(max_workers=max_concurrency) as executor:
        features = {executor.submit(run_cmd, cmd, False): cmd for cmd in cmds}
        for future in as_completed(features):
            ret, stdout, stderr = future.result()
            if ret != 0:
                stdout = " ".join(stdout.split())
                stderr = " ".join(stderr.split())
                log_message(
                    f"Error running cmd=\"{features[future]}\" ret=\"{ret}\" stdout=\"{stdout}\" stderr=\"{stderr}\"")
                success = False
            else:
                success_cnt += 1
                print(
                    f"\t{success_cnt} out of {len(features)} cmds have succeeded.")
    return success


def check_command_exists(cmd: str, exit_on_err: bool = True) -> Tuple[int, str, str]:
    """Check if a command exists in PATH.

    Args:
        cmd: Command name to check
        exit_on_err: If True, raise error if command not found

    Returns:
        Tuple of (return_code, stdout, stderr)
    """
    print(f"Checking whether cmd \"{cmd}\" exists in PATH...")
    return run_cmd(f'command -v {cmd} >/dev/null 2>&1', exit_on_err=exit_on_err)


def version_check(min_ver: str, actual_ver: str, module_name: str) -> None:
    """Check if actual version meets minimum requirement."""
    if not actual_ver:
        raise RuntimeError(f"{module_name} not found")

    if not min_ver:
        print(f"Using {module_name} version {actual_ver}")
        return

    parts_actual = list(map(int, actual_ver.split('.')))
    parts_min = list(map(int, min_ver.split('.')))

    # Pad with zeros to equal length
    max_len = max(len(parts_actual), len(parts_min))
    parts_actual.extend([0] * (max_len - len(parts_actual)))
    parts_min.extend([0] * (max_len - len(parts_min)))

    res = (parts_actual > parts_min) - (parts_actual < parts_min)
    if res < 0:
        raise RuntimeError(
            f"{module_name} version {actual_ver} does not meet the minimum requirement {min_ver}")

    print(f"Using {module_name} version {actual_ver}")
    return


def is_interface_up(interface: str) -> bool:
    """Check if a network interface is up and has an IP address."""
    try:
        # Check if interface exists
        returncode, stdout, _ = run_cmd(
            f'ip addr show {interface}', exit_on_err=False)
        if returncode != 0:
            return False

        # Check if it's a primary name
        if not Path(f"/sys/class/net/{interface}").is_dir():
            return False

        # Check if interface is DOWN
        if 'DOWN' in stdout:
            return False

        # Check if IP address is assigned
        returncode, stdout, _ = run_cmd(
            f'ip -4 addr show dev {interface}', exit_on_err=False)

        return 'inet ' in stdout
    except Exception as e:
        log_message(
            f"Error: is_interface_up({interface}) failed to run: {str(e)}")
        return False


def find_tcp_interface() -> Optional[str]:
    """Find the first UP TCP interface."""
    try:
        # Get all IP addresses
        _, stdout, _ = run_cmd('hostname -I', exit_on_err=False)
        ip_addresses = stdout.strip().split()

        for ip_addr in ip_addresses:
            # Find interface for this IP
            _, stdout, _ = run_cmd('ip -br -4 a sh', exit_on_err=False)

            for line in stdout.splitlines():
                if f"{ip_addr}/" in line:
                    interface = line.split()[0]
                    if interface and is_interface_up(interface):
                        return interface

        return None
    except subprocess.CalledProcessError:
        return None


def call_func_with_retry(func, max_wait: int, sleep_interval: int, *args, **kwargs) -> Optional[str]:
    """Call a function with retry logic.

    Args:
        func: Function to call
        max_wait: Maximum time to wait in seconds
        sleep_interval: Time to sleep between retries in seconds
        *args: Positional arguments to pass to func
        **kwargs: Keyword arguments to pass to func

    Returns:
        Result from func if successful, None if timeout
    """
    start_time = time.time()

    while True:
        result = func(*args, **kwargs)
        if result:
            return result

        elapsed = time.time() - start_time
        if elapsed >= max_wait:
            return None

        time.sleep(sleep_interval)


def get_efa_topology(efa_name):
    """Get PCIe topology - handles any domain number.
    Example for sys/devices/pci0000:bb/0000:bb:00.0/0000:bc:00.0/0000:bd:01.0/0000:c6:00.0

    CPU (NUMA Node 0)
    |
    └─ Root Complex [pci0000:bb]
        |
        └─ Root Port [0000:bb:00.0]
            |
            └─ PCIe Switch Upstream [0000:bc:00.0]
                |
                └─ PCIe Switch [0000:bd:xx.x] ← This is "the switch"
                    |
                    ├─ [0000:bd:01.0] → EFA [0000:c6:00.0]
                    ├─ [0000:bd:01.1] → EFA [0000:c7:00.0]
                    ├─ [0000:bd:01.2] → EFA [0000:c8:00.0]
                    ├─ [0000:bd:01.3] → EFA [0000:c9:00.0]
                    └─ ...

    """
    real_path = os.path.realpath(f"/sys/class/infiniband/{efa_name}/device")

    # Match full PCIe address: DOMAIN:BUS:DEVICE.FUNCTION
    # e.g., 0000:c6:00.0, 0001:3b:00.0
    pci_pattern = re.compile(
        r'[0-9a-fA-F]{4}:[0-9a-fA-F]{2}:[0-9a-fA-F]{2}\.[0-9a-fA-F]')

    parts = real_path.split('/')
    pci_parts = [p for p in parts if pci_pattern.match(p)]

    # Also capture root complex (pciXXXX:XX format)
    root_pattern = re.compile(r'pci([0-9a-fA-F]{4}:[0-9a-fA-F]{2})')
    root_complex = None
    for p in parts:
        match = root_pattern.match(p)
        if match:
            root_complex = match.group(1)
            break

    return {
        "name": efa_name,
        "path": real_path,
        "root_complex": root_complex,
        "pci_parts": pci_parts,
    }


def filter_by_pci_bus(efa_list, instance_type):
    if instance_type in ["p5.48xlarge", "p5e.48xlarge"]:
        def get_key(t): return t["pci_parts"][1]
    elif instance_type == "p5en.48xlarge":
        def get_key(t): return (t["pci_parts"][1],
                                t["pci_parts"][2].split(':')[2].split('.')[0])
    else:
        raise NotImplementedError(
            f"filter_by_pci_bus for {instance_type} is not implemented")

    seen = set()
    for efa_name in efa_list:
        topology = get_efa_topology(efa_name)
        if len(topology["pci_parts"]) != 4:
            raise RuntimeError(
                f"Error: {efa_name} has {len(topology['pci_parts'])} PCI parts, expected 4. pci_parts={topology['pci_parts']}, path={topology['path']}")
        key = get_key(topology)
        if key not in seen:
            seen.add(key)
            yield efa_name


def filter_efa_non_gds(efa_list: List[str], instance_type: str) -> List[str]:
    """Filter EFA interfaces for non-GDS configurations based on instance type.

    Args:
        efa_list: List of available EFA interface names
        instance_type: EC2 instance type

    Returns:
        Filtered list of EFA interfaces to configure
    """
    if not efa_list:
        return efa_list

    if instance_type == "p6-b200.48xlarge":
        # p6-b200.48xlarge has 8 EFA interfaces. Add all.
        return efa_list

    if instance_type == "p6-b300.48xlarge":
        # p6-b300.48xlarge has 16 EFA interfaces. Add all.
        return efa_list

    if instance_type == "p6e-gb200.36xlarge":
        # p6e-gb200.36xlarge has 16 EFA interfaces. We only add those connected to host/cpu.
        def should_include(intf: str) -> bool:
            link_width_path = Path(
                f"/sys/class/infiniband/{intf}/device/current_link_width")
            if link_width_path.exists():
                link_width = int(link_width_path.read_text().strip())
                return link_width != 16
            return True
        return [intf for intf in efa_list if should_include(intf)]

    if instance_type in ["p5.48xlarge", "p5e.48xlarge"]:
        # P5 instance type supports 32 network interfaces,
        # by default we add 8, selecting 1 every 4 (1 per PCI bus)
        return list(filter_by_pci_bus(efa_list, instance_type))

    if instance_type == "p5en.48xlarge":
        # P5en instance type supports 16 network interfaces,
        # by default we add 8, selecting 1 every 2
        return list(filter_by_pci_bus(efa_list, instance_type))

    # Other instances: Configure all available EFA interfaces by default
    return efa_list


def filter_efa_gds(efa_list: List[str], instance_type: str) -> List[str]:
    """Filter EFA interfaces for GDS configurations.

    Args:
        efa_list: List of available EFA interface names
        instance_type: EC2 instance type

    Returns:
        Filtered list of EFA interfaces (currently returns all)
    """
    if instance_type not in GDS_SUPPORTED_INSTANNCES:
        raise RuntimeError(
            f"Error: Instance type {instance_type} does not support Lustre GDS.")
    return efa_list


def find_and_filter_efa_interfaces(allow_no_efa: bool, is_gds: bool, instance_type: str) -> List[str]:
    """Find and filter EFA interfaces based on instance type and configuration.

    Args:
        allow_no_efa: If True, allow script to continue without EFA interfaces
        is_gds: If True, optimize for GDS (GPU Direct Storage)
        instance_type: EC2 instance type

    Returns:
        List of filtered EFA interface names
    """
    print("Checking EFA devices...")
    efa_list = []
    infiniband_dir = Path("/sys/class/infiniband")

    if not infiniband_dir.is_dir():
        log_message("Warning: /sys/class/infiniband directory not found")
        return efa_list

    for interface_path in infiniband_dir.iterdir():
        driver_path = interface_path / "device" / "driver"
        if driver_path.exists():
            driver = driver_path.resolve().name
            if driver == "efa":
                efa_list.append(interface_path.name)
    efa_list.sort()

    print(f"Found {len(efa_list)} available EFA device(s)")

    if not efa_list:
        if not allow_no_efa:
            raise RuntimeError(
                "No EFA device found. Exit because --allow-no-efa is not specified")
        log_message("Warning: No EFA device found under /sys/class/infiniband")

    if is_gds:
        return filter_efa_gds(efa_list, instance_type)
    return filter_efa_non_gds(efa_list, instance_type)


def parse_arguments() -> argparse.Namespace:
    """Parse command line arguments."""
    parser = argparse.ArgumentParser(
        description='Configure EFA for FSx Lustre client',
        formatter_class=argparse.RawDescriptionHelpFormatter
    )

    parser.add_argument(
        '--optimized-for-gds',
        action='store_true',
        help="Optimize EFA setup for GDS IO"
    )

    parser.add_argument(
        '--tcp-name',
        type=str,
        help="Specify the TCP interface name to use for EFA. (default: the first UP interface returned by 'hostname -I')"
    )
    parser.add_argument(
        '--disable-dmesg',
        action='store_true',
        help='Disable dmesg output.'
    )
    parser.add_argument(
        '--allow-no-efa',
        action='store_true',
        help='Allow the script to continue without EFA interfaces. It still requires a EFA driver.'
    )
    parser.add_argument(
        '--tcp-wait-time',
        type=int,
        default=120,
        help='Time to wait for TCP interface to be up (default: 120 seconds).'
    )
    parser.add_argument(
        '--tcp-wait-interval',
        type=int,
        default=1,
        help='Interval between TCP interface checks (default: 1 seconds).'
    )
    parser.add_argument(
        '--internal-check-only',
        action='store_true',
        help=argparse.SUPPRESS  # Hidden option used by setup.sh
    )

    return parser.parse_args()


def ensure_root_user() -> None:
    """Ensure the script is running as root user."""
    if os.geteuid() != 0:
        print(
            f'"{THIS_FILE_NAME}" must be run as root. Please use sudo.', file=sys.stderr)
        sys.exit(1)


def setup_enable_dmesg_flag(args: argparse.Namespace) -> None:
    """Set the global ENABLE_DMESG flag based on command line arguments."""
    global ENABLE_DMESG
    ENABLE_DMESG = not args.disable_dmesg


def check_required_commands() -> None:
    """Checking required commands..."""
    for cmd in ['lfs', 'lctl', 'ip', 'curl', 'modinfo']:
        check_command_exists(cmd)


def check_lustre_userspace_ver() -> None:
    """Checking Lustre userspace version..."""
    returncode, stdout, _ = run_cmd('lfs --version', exit_on_err=False)
    lfs_version = (stdout.split() + ["", ""])[1] if returncode == 0 else ""
    version_check("2.15", lfs_version, "Lustre client")


def check_tcp_interface(args: argparse.Namespace) -> str:
    """Check and validate TCP interface availability.

    Args:
        args: Parsed command line arguments

    Returns:
        Name of the validated TCP interface

    Raises:
        RuntimeError: If interface is not found or not up within timeout
    """
    print("Checking TCP interface...")
    if args.tcp_name:
        eth_intf = args.tcp_name
        result = call_func_with_retry(
            is_interface_up, args.tcp_wait_time, args.tcp_wait_interval, eth_intf)
        if not result:
            raise RuntimeError(
                f"Primary interface {eth_intf} does not exist or is not up. Timeout after {args.tcp_wait_time} second(s).")
    else:
        eth_intf = call_func_with_retry(
            find_tcp_interface, args.tcp_wait_time, args.tcp_wait_interval)
        if not eth_intf:
            raise RuntimeError(
                f"No up TCP interface found. Timeout after {args.tcp_wait_time} second(s).")
    print(f"Found TCP interface: {eth_intf}")
    return eth_intf


def check_efa_driver_ver() -> None:
    """Check EFA driver version meets minimum requirements."""
    print("Checking EFA driver version...")
    _, efa_version, _ = run_cmd(
        "modinfo efa | awk '/^version:/ {print $2}' | sed 's/[^0-9.]//g'")
    version_check(MIN_EFA_VERSION, efa_version.strip(), "EFA driver")


def get_instance_type() -> str:
    """Retrieve EC2 instance type from metadata service.

    Returns:
        EC2 instance type string

    Raises:
        RuntimeError: If unable to retrieve instance type
    """
    _, stdout, _ = run_cmd(
        'curl -s -X PUT "http://169.254.169.254/latest/api/token" -H "X-aws-ec2-metadata-token-ttl-seconds: 21600"'
    )
    token = stdout.strip()

    _, stdout, _ = run_cmd(
        f'curl -s -H "X-aws-ec2-metadata-token: {token}" http://169.254.169.254/latest/meta-data/instance-type'
    )
    instance_type = stdout.strip()
    if not instance_type:
        raise RuntimeError(
            "Unable to get EC2 instance type from metadata service")
    print(f"Detected instance type: {instance_type}")
    return instance_type


def check_kefalnd_ver(instance_type: str) -> None:
    """Check kefalnd version for P6+ instances.

    Args:
        instance_type: EC2 instance type
    """
    # Check kefalnd version for p6 instances
    need_check = any(instance_type.startswith(prefix)
                     for prefix in P6PLUS_INSTACES_PREFIX)

    if not need_check:
        return

    print("Checking kefalnd version...")
    _, stdout, _ = run_cmd("modinfo kefalnd | awk '/^version:/ {print $2}'")
    kefalnd_version = stdout.strip()
    version_check(P6PLUS_MIN_KEFALND_VERSION, kefalnd_version, "kefalnd")


def load_lustre_efa_modules(eth_intf: str) -> None:
    """Load Lustre and EFA kernel modules.

    Args:
        eth_intf: TCP interface name to use for kefalnd
    """
    print("Loading Lustre/EFA modules...")
    run_cmd('/sbin/modprobe lnet')
    run_cmd(f'/sbin/modprobe kefalnd ipif_name={eth_intf}')
    run_cmd('/sbin/modprobe ksocklnd')
    run_cmd('lnetctl lnet configure')


def configure_tcp_interfaces(eth_intf: str) -> None:
    """Configure Lustre TCP network interface.

    Args:
        eth_intf: TCP interface name to configure
    """
    print("Configuring TCP interface...")
    # Try to delete existing TCP interface (may fail if none exists)
    run_cmd('lnetctl net del --net tcp', exit_on_err=False)
    run_cmd(f'lnetctl net add --net tcp --if {eth_intf}')


def get_client_tag() -> str:
    """Get Lustre client version tag.

    Returns:
        Client version tag as string

    Raises:
        ValueError: If unable to extract tag from version string
    """
    def extract_tag(version: str) -> str:
        """Extract tag from version string.

        Input can be: 2.15.6-1.fsx23.el9, 2.15.6-23.amzn2023, 2.15.6-1fsx23
        """
        # Try fsx pattern first (priority)
        match = re.search(r'fsx(\d+)', version)
        if match:
            return match.group(1)

        # If no fsx, try -NN. pattern
        match = re.search(r'-(\d+)\.', version)
        if match:
            return match.group(1)

        raise ValueError(f"Unable to extract tag from version: {version}")

    print("Getting Lustre client version tag...")

    if check_command_exists("dnf", exit_on_err=False)[0] == 0:
        _, stdout, _ = run_cmd(
            "dnf list installed lustre-client | grep lustre | tail -1 | awk '{print $2}'")
    elif check_command_exists("yum", exit_on_err=False)[0] == 0:
        _, stdout, _ = run_cmd(
            "yum list installed | grep lustre | tail -1 | awk '{print $2}'")
    elif check_command_exists("dpkg", exit_on_err=False)[0] == 0:
        _, stdout, _ = run_cmd(
            "dpkg -l | grep lustre | grep utils | tail -1 | awk '{print $3}'")
    elif check_command_exists("apt", exit_on_err=False)[0] == 0:
        _, stdout, _ = run_cmd(
            "apt list --installed | grep lustre | grep utils | tail -1 | awk '{print $2}'")
    else:
        raise RuntimeError(
            "No supported package manager found (dnf, yum, dpkg, apt)")

    tag = extract_tag(stdout.strip())
    print(f"Found client tag: {tag}")
    return tag


def check_enable_cpt_opt(efa_device_list, tag: Optional[str] = None) -> bool:
    """Check if CPT optimization should be enabled based on client tag.

    Args:
        tag: Client version tag, will be fetched if not provided

    Returns:
        True if CPT optimization should be enabled
    """
    if len(efa_device_list) <= 1:
        """
        If there's only one EFA intf, all CPU must use this EFA no matter what.
        So there's no point configuring CPT optimization.
        """
        return False

    if tag is None:
        tag = get_client_tag()
    return int(tag) >= MIN_CPT_OPT_TAG


def check_del_all_efa_at_once(tag: Optional[str] = None) -> bool:
    """Check if all EFA interfaces can be deleted at once.

    Args:
        tag: Client version tag, will be fetched if not provided

    Returns:
        True if bulk deletion is supported
    """
    if tag is None:
        tag = get_client_tag()
    return int(tag) >= MIN_DEL_ALL_EFA_TAG


def write_cpt_config_file(contents: str, dryrun: bool = False) -> None:
    """Write CPT configuration to modprobe.conf file.

    Args:
        contents: Configuration content to write
        dryrun: If True, skip actual file write
    """
    print(f"\tConfiguration to write to {CPT_CONFIG_FILE_PATH}:")
    print(f"{contents}")

    if dryrun:
        print(f"\tDry run mode - skipping file write")
        return

    try:
        with open(CPT_CONFIG_FILE_PATH, "r") as file:
            file_contents = file.read()
    except FileNotFoundError:
        file_contents = ""

    if not contents.endswith("\n"):
        contents += "\n"

    pattern = re.compile(
        re.escape(START_MARKER) + r'.*?' + re.escape(END_MARKER) + r'\n?',
        re.DOTALL
    )

    if pattern.search(file_contents):
        new_contents = pattern.sub(contents, file_contents)
    else:
        new_contents = file_contents + \
            ("\n" if file_contents and not file_contents.endswith("\n") else "") + \
            contents

    with open(CPT_CONFIG_FILE_PATH, 'w') as f:
        f.write(new_contents)

    print(f"\tSuccessfully wrote configuration to {CPT_CONFIG_FILE_PATH}")


def get_num_numas() -> int:
    """Get the number of NUMA nodes.

    Returns:
        Number of NUMA nodes

    Raises:
        RuntimeError: If number of NUMA nodes is invalid
    """
    _, stdout, _ = run_cmd("lscpu | grep 'NUMA node(s):' | awk '{print $3}'")
    num_numa_nodes = int(stdout.strip())
    if num_numa_nodes <= 0:
        raise RuntimeError(
            f"Invalid number of NUMA nodes: {num_numa_nodes}")
    return num_numa_nodes


def get_num_cpus() -> int:
    """Get the number of CPUs.

    Returns:
        Number of CPUs

    Raises:
        RuntimeError: If number of CPUs is invalid
    """
    _, stdout, _ = run_cmd("lscpu | grep '^CPU(s):' | awk '{print $2}'")
    num_cpus = int(stdout.strip())
    if num_cpus <= 0:
        raise RuntimeError(f"Invalid number of CPUs: {num_cpus}")
    return num_cpus


def get_numa_to_efas(efa_device_list: List[str], num_numa_nodes: int) -> List[List[str]]:
    """Get a (non empty) list of EFA devices per NUMA node.

    Args:
        efa_device_list: List of EFA device names
        num_numa_nodes: Number of NUMA nodes

    Returns:
        List of EFA devices per NUMA node

    Raises:
        RuntimeError: If NUMA node is out of range or no EFAs found for a node
    """
    numa_to_efas = [[] for _ in range(num_numa_nodes)]
    for efa_device in efa_device_list:
        _, stdout, _ = run_cmd(
            f"cat /sys/class/infiniband/{efa_device}/device/numa_node")
        numa_node = int(stdout.strip())
        if numa_node == -1 and num_numa_nodes == 1:
            numa_node = 0
        if numa_node >= num_numa_nodes or numa_node < 0:
            raise RuntimeError(
                f"NUMA node for {efa_device} is {numa_node} which is not in range [0, {num_numa_nodes})")
        numa_to_efas[numa_node].append(efa_device)

    # Verify all NUMA nodes have at least one EFA
    for idx, efas in enumerate(numa_to_efas):
        if not efas:
            raise RuntimeError(
                f"No EFA devices found for NUMA node {idx}")
    return numa_to_efas


def get_numa_to_cpus(num_numa_nodes: int, num_cpus: int) -> List[List[int]]:
    """Get a (non empty) list of CPUs per NUMA node.

    Args:
        num_numa_nodes: Number of NUMA nodes
        num_cpus: Total number of CPUs

    Returns:
        List of CPUs per NUMA node (sorted)

    Raises:
        RuntimeError: If CPU parsing fails or CPU is out of range
    """
    _, stdout, _ = run_cmd("lscpu --parse=CPU,NODE")
    numa_to_cpus = [[] for _ in range(num_numa_nodes)]
    for line in stdout.split("\n"):
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        cpu, numa = line.split(",")
        cpu_id = int(cpu)
        if cpu_id >= num_cpus or cpu_id < 0:
            raise RuntimeError(
                f"CPU {cpu_id} is not in range [0, {num_cpus})")
        numa_to_cpus[int(numa)].append(cpu_id)

    # Verify all NUMA nodes have CPUs and sort them
    for idx, cpus in enumerate(numa_to_cpus):
        if not cpus:
            raise RuntimeError(
                f"No CPUs found for NUMA node {idx}")
        cpus.sort()
    return numa_to_cpus


def get_efa_to_cpus(numa_to_efas: List[List[str]], numa_to_cpus: List[List[int]]) -> Dict[str, List[int]]:
    """Get a (non empty) list of CPUs per EFA device.

    Distributes CPUs evenly across EFA devices within each NUMA node.

    Args:
        numa_to_efas: List of EFA devices per NUMA node
        numa_to_cpus: List of CPUs per NUMA node

    Returns:
        Dictionary mapping EFA device name to list of CPU IDs
    """
    efa_to_cpus = {}
    for numa_node, cpus in enumerate(numa_to_cpus):
        efas = numa_to_efas[numa_node]

        base_size = len(cpus) // len(efas)
        extra = len(cpus) % len(efas)
        cpu_idx = 0
        for i, efa_device in enumerate(efas):
            size = base_size + (1 if i < extra else 0)
            efa_to_cpus[efa_device] = cpus[cpu_idx:cpu_idx+size]
            cpu_idx += size
    return efa_to_cpus


def get_ptlrpc_per_cpt_max():
    num_cpus = get_num_cpus()
    if num_cpus >= 64:
        return 32
    return 0


def get_ksocklnd_credits():
    num_cpus = get_num_cpus()
    if num_cpus >= 64:
        return 2560
    elif num_cpus >= 32:
        return 1280
    return 256


def setup_cpt_config_file(efa_device_list: List[str], enable_cpt_opt: bool = True, dryrun: bool = False) -> None:
    """Setup CPT (CPU Partition Table) configuration file.

    Args:
        efa_device_list: List of EFA device names
        enable_cpt_opt: If True, enable CPT optimization
        dryrun: If True, skip actual file write
    """
    print(f"Setting up cpt_config_file at {CPT_CONFIG_FILE_PATH}...")

    if not enable_cpt_opt:
        contents = [
            START_MARKER,
            f"options ksocklnd credits={get_ksocklnd_credits()}",
            f"options ptlrpc ptlrpcd_per_cpt_max={get_ptlrpc_per_cpt_max()}",
            END_MARKER
        ]
        contents = "\n".join(contents)
        write_cpt_config_file(contents, dryrun)
        return

    num_numa_nodes = get_num_numas()
    print(f"\tNumber of NUMA nodes: {num_numa_nodes}")
    numa_to_efas = get_numa_to_efas(efa_device_list, num_numa_nodes)
    num_cpus = get_num_cpus()
    print(f"\tNumber of CPUs: {num_cpus}")
    numa_to_cpus = get_numa_to_cpus(num_numa_nodes, num_cpus)
    efa_to_cpus = get_efa_to_cpus(numa_to_efas, numa_to_cpus)

    # prepare cpu pattern
    cpu_pattern = []
    for idx, efa in enumerate(efa_device_list):
        cpu_pattern.append(f"{idx}{efa_to_cpus[efa]}".replace(" ", ""))
    cpu_pattern = " ".join(cpu_pattern)

    # modprobe.conf contents
    contents = [
        START_MARKER,
        f"options libcfs cpu_npartitions={len(efa_device_list)} cpu_pattern=\"{cpu_pattern}\"",
        f"options ksocklnd credits={get_ksocklnd_credits()}",
        f"options ptlrpc ptlrpcd_per_cpt_max={get_ptlrpc_per_cpt_max()}",
        END_MARKER
    ]
    contents = "\n".join(contents)
    write_cpt_config_file(contents, dryrun)


def cleanup_efa_interfaces() -> None:
    """Remove existing EFA network interfaces from Lustre configuration."""
    print("Cleaning up existing EFA interfaces...")
    _, stdout, _ = run_cmd(
        "lnetctl net show --net efa | grep '0:' | awk '{print $2}'", exit_on_err=False)
    if not stdout.strip():
        return

    # # TODO: enable this
    # if check_del_all_efa_at_once():
    #     run_cmd('lnetctl net del --net efa')
    #     return

    cmds = []
    devices = []
    for line in stdout.strip().split("\n"):
        efa_device = line.strip()
        devices.append(efa_device)
        cmds.append(f'lnetctl net del --net efa --if {efa_device}')

    if len(devices) == 0:
        return

    print(f"\tRemoving in parallel the EFA interfaces {devices}...")
    if not run_cmd_in_parallel(cmds):
        raise RuntimeError("Error removing EFA interfaces")
    print("\tSuccessfully removed all EFA interfaces")


def configure_efa_interfaces(efa_device_list: List[str], enable_cpt_opt: bool) -> None:
    """Configure EFA network interfaces for Lustre.

    Args:
        efa_device_list: List of EFA device names to configure
        enable_cpt_opt: If True, enable CPT optimization
    """
    cleanup_efa_interfaces()

    print(f"Configuring EFA interfaces...")

    peer_credits = 32
    if len(efa_device_list) > 4:
        peer_credits = 128

    cmds = []
    for idx, efa_device in enumerate(efa_device_list):
        cmd = f"lnetctl net add --net efa --if {efa_device} --peer-credits {peer_credits}"
        cmd += f" --cpt {idx}" if enable_cpt_opt else ""
        cmds.append(cmd)

    print(f"\tAdding in parallel the EFA interfaces {efa_device_list}...")
    if not run_cmd_in_parallel(cmds):
        raise RuntimeError("Error adding EFA interfaces")
    print("\tSuccessfully added all EFA interfaces")


def configure_discovery_and_udsp(num_efa_devices: int) -> None:
    """Configure Lustre discovery and UDSP (Unified Data Stream Protocol) rules.

    Args:
        num_efa_devices: Number of EFA devices configured
    """
    if num_efa_devices > 0:
        print("Enabling Lustre discovery...")
        run_cmd('lnetctl set discovery 1')
        print("Setting EFA as the preferred Lustre network (udsp)...")

        ret, stdout, stderr = run_cmd(
            'lnetctl udsp add --src efa --priority 0', exit_on_err=False)
        # Error 114 with "Operation already in progress" is expected if rule already exists
        if ret != 0 and (ret != 114 or "Operation already in progress" not in stderr):
            raise RuntimeError(
                f"lnetctl udsp add --src efa --priority 0 failed. ret={ret} stdout={stdout} stderr={stderr}")
    else:
        log_message(
            "Warning: No EFA device found or added. Discovery and UDSP rules are not set.")


def main() -> None:
    """Main function to configure EFA for FSx Lustre client."""
    args = parse_arguments()
    ensure_root_user()
    setup_enable_dmesg_flag(args)

    print(f"Started {THIS_FILE_NAME} at {datetime.now()}")

    check_required_commands()
    check_lustre_userspace_ver()

    eth_intf = check_tcp_interface(args)
    check_efa_driver_ver()

    instance_type = get_instance_type()
    check_kefalnd_ver(instance_type)

    efa_device_list = find_and_filter_efa_interfaces(
        args.allow_no_efa, args.optimized_for_gds, instance_type)

    enable_cpt_opt = check_enable_cpt_opt(efa_device_list)
    setup_cpt_config_file(efa_device_list, enable_cpt_opt,
                          dryrun=args.internal_check_only)

    if args.internal_check_only:
        return

    load_lustre_efa_modules(eth_intf)
    configure_tcp_interfaces(eth_intf)
    configure_efa_interfaces(efa_device_list, enable_cpt_opt)
    configure_discovery_and_udsp(len(efa_device_list))

    # Start lustre module
    print("Loading Lustre module...")
    run_cmd('/sbin/modprobe lustre')

    # Count added EFA interfaces
    _, stdout, _ = run_cmd('lnetctl net show')
    efa_count = stdout.count('@efa')
    log_message(
        f"Successfully configured and added {efa_count} EFA interface(s).")


if __name__ == '__main__':
    try:
        main()
    except Exception as e:
        log_message(f"Error: {e}")
        log_print_exception()
        sys.exit(1)
